def shannon_entropy(grid):
    """Shannon entropy of a binary grid."""
    p = np.mean(grid)
    if p == 0 or p == 1:
        return 0.0
    return -p * np.log2(p) - (1 - p) * np.log2(1 - p)


def tsallis_entropy(grid, q=2):
    """Tsallis entropy (q=2) of a binary grid."""
    p = np.mean(grid)
    if p == 0 or p == 1:
        return 0.0
    return (1 - (p**q + (1 - p)**q)) / (q - 1)


