def life(g):
    n = (np.roll(g,1,0)+np.roll(g,-1,0)+np.roll(g,1,1)+np.roll(g,-1,1)
         + np.roll(np.roll(g,1,0),1,1)+np.roll(np.roll(g,1,0),-1,1)
         + np.roll(np.roll(g,-1,0),1,1)+np.roll(np.roll(g,-1,0),-1,1))
    return (((g==1)&((n==2)|(n==3))) | ((g==0)&(n==3))).astype(np.float32)

