    x, y = x0, y0
    for _ in range(n_burn):
        x, y = step(a, x, y)
    v1 = np.array([1e-8, 0.0]); v2 = np.array([0.0, 1e-8])
    s1 = 0.0; hist = []
    for _ in range(n_meas):
        x, y = step(a, x, y)
        J = np.array([[-2.0*a*x, 1.0], [B, 0.0]])
        M = J @ np.column_stack([v1, v2])
        Q, R = np.linalg.qr(M)
        s1 += np.log(abs(R[0,0]))
        v1, v2 = Q[:,0], Q[:,1]
        if _ % 5000 == 0:
            hist.append(s1/(_+1))
    return s1/n_meas, hist, x, y

